	'Viscose Paisley - Paars Multi' => 'Viscose paisley - Purple multi',
	'Imitatieleer Zacht Stretch - Metallic Groen' => 'Soft stretch faux leather - Metallic green',
	'Geborstelde Mantelstof geruit - beige lichtroos' => 'Brushed checked coating fabric - beige light pink',
